}


python
def chainInspectionFloorTicket(head, k):
    a=head
    out=[]
    node=a
    while node:
        out.append(node.val)
        node=node.next
    return min(out,default=0)


java
class Solution {
  public int chainInspectionFloorTicket(ListNode head, int k) {
    ListNode a=head; List<Integer> out=new ArrayList<>();
    {for(ListNode node=a;node!=null;node=node.next)out.add(node.val);}
    int answer=out.isEmpty()?0:out.get(0);for(int x:out)answer=Math.min(answer,x);return answer;
  }
}
